mapper.select:
select e.*, h.accountname as hyaccount, h.name as hyname from eatlog e left join huiyuan h on h.id=e.hyid
where 1=1
and hyid=#{hyid}

select distinct t1.* from eatlog t1, eatlog t2, eatlog t3 where t1.calorie >= 800 and t2.calorie >=800 and t3.calorie>=800 and ( (DATEDIFF(t1.createtime,t2.createtime)= 1 and DATEDIFF(t1.createtime,t3.createtime) = 2 and DATEDIFF(t2.createtime,t3.createtime) =1) -- t1, t2, t3 or (DATEDIFF(t2.createtime,t1.createtime)= 1 and DATEDIFF(t2.createtime,t3.createtime) = 2 and DATEDIFF(t1.createtime,t3.createtime) =1) -- t2, t1, t3 or (DATEDIFF(t3.createtime,t2.createtime)= 1 and DATEDIFF(t3.createtime,t1.createtime) = 2 and DATEDIFF(t2.createtime,t1.createtime) =1) -- t2, t1, t3 )
and t1.hyid=#{hyid}
order by t1.id
